-- State transitions declared for StockMove (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION inventory.stock_moves_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('assigned', 'cancel'), ('assigned', 'done'), ('confirmed', 'assigned'), ('confirmed', 'cancel'), ('confirmed', 'done'), ('confirmed', 'partially_available'), ('draft', 'cancel'), ('draft', 'confirmed'), ('draft', 'waiting'), ('partially_available', 'assigned'), ('partially_available', 'cancel'), ('partially_available', 'done'), ('waiting', 'cancel'), ('waiting', 'confirmed'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: stock_moves.state % -> %', OLD."state", NEW."state";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS stock_moves_state_transition_check ON inventory.stock_moves;
CREATE TRIGGER stock_moves_state_transition_check
    BEFORE UPDATE OF "state" ON inventory.stock_moves
    FOR EACH ROW EXECUTE FUNCTION inventory.stock_moves_state_transition_check();
